package com.aamoreadditions.recipe;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.*;

/** Efficient-Smelting recipe data (generated by tools/gen_efficient_smelting.py) + GUI/JEI wiring. */
class EfficientSmeltingTest {
    static final Path DIR = Path.of("src/main/resources/data/aamoreadditions/recipe/efficient_smelting");
    static String src(String p) throws Exception { return Files.readString(Path.of("src/main/java/com/aamoreadditions/" + p)); }

    /** IE RecipeMetals (name -> hasOre), exact, plus titanium & iridium. */
    static final Map<String, Boolean> METALS = new LinkedHashMap<>();
    static {
        for (String m : "iron gold copper aluminum lead silver nickel uranium tin zinc platinum tungsten osmium cobalt ardite titanium iridium".split(" ")) METALS.put(m, true);
        for (String m : "constantan electrum steel bronze brass invar rose_gold manyullyn".split(" ")) METALS.put(m, false);
    }
    static final Set<String> VANILLA = Set.of("iron", "gold", "copper");

    static JsonObject read(Path p) {
        try { return JsonParser.parseString(Files.readString(p)).getAsJsonObject(); } catch (Exception e) { throw new RuntimeException(p.toString(), e); }
    }

    @Test void everyMetalHasExactlyTheFixedYieldRecipes() throws Exception {
        int total = 0;
        try (Stream<Path> dirs = Files.list(DIR)) { assertEquals(new TreeSet<>(METALS.keySet()), new TreeSet<>(dirs.map(d -> d.getFileName().toString()).toList())); }
        for (var e : METALS.entrySet()) {
            String m = e.getKey();
            Map<String, Object[]> want = new LinkedHashMap<>(); // file -> {input tag, slots, count}
            if (e.getValue()) {
                want.put("raw_x2", new Object[]{"c:raw_materials/" + m, 2, 3});
                want.put("raw_x3", new Object[]{"c:raw_materials/" + m, 3, 5});
                want.put("ore", new Object[]{"c:ores/" + m, 1, 2});
                want.put("raw_block", new Object[]{"c:storage_blocks/raw_" + m, 1, 16});
            }
            want.put("dust", new Object[]{"c:dusts/" + m, 1, 1});
            try (Stream<Path> fs = Files.list(DIR.resolve(m))) {
                assertEquals(new TreeSet<>(want.keySet()), new TreeSet<>(fs.map(f -> f.getFileName().toString().replace(".json", "")).toList()), m);
            }
            for (var w : want.entrySet()) {
                var j = read(DIR.resolve(m).resolve(w.getKey() + ".json"));
                assertEquals("aamoreadditions:efficient_smelting", j.get("type").getAsString());
                assertFalse(j.has("slots") || j.has("ingredient"));
                var ings = j.getAsJsonArray("ingredients");
                assertEquals(w.getValue()[1], ings.size()); // one entry per input slot (input 3 = extra)
                for (var el : ings) {
                    assertEquals(w.getValue()[0], el.getAsJsonObject().get("tag").getAsString());
                    assertEquals(1, el.getAsJsonObject().size()); // no count: one item per slot
                }
                var res = j.getAsJsonObject("result");
                assertEquals("c:ingots/" + m, res.get("tag").getAsString()); // tag result -> same-tag choice applies
                assertEquals(w.getValue()[2], res.get("count").getAsInt());
                assertFalse(j.has("time"), m); // default time (raw blocks 8x via tag detection)
                if (VANILLA.contains(m) && !w.getKey().equals("dust")) assertFalse(j.has("neoforge:conditions"), m);
                else {
                    var c = j.getAsJsonArray("neoforge:conditions");
                    assertEquals(2, c.size());
                    Set<String> tags = new HashSet<>();
                    for (var el : c) {
                        var o = el.getAsJsonObject();
                        assertEquals("neoforge:not", o.get("type").getAsString());
                        var v = o.getAsJsonObject("value");
                        assertEquals("neoforge:tag_empty", v.get("type").getAsString());
                        tags.add(v.get("tag").getAsString());
                    }
                    assertEquals(Set.of((String) w.getValue()[0], "c:ingots/" + m), tags);
                }
                total++;
            }
        }
        assertEquals(17 * 5 + 8, total);
    }

    @Test void recipeTypeAndSerializerRegistered() throws Exception {
        var mr = src("recipe/ModRecipes.java");
        assertTrue(mr.contains("TYPES.register(\"efficient_smelting\""));
        assertTrue(mr.contains("SERIALIZERS.register(\"efficient_smelting\", EfficientSmeltingRecipe.Serializer::new)"));
        var r = src("recipe/EfficientSmeltingRecipe.java");
        assertTrue(r.contains("Codec.list(Ingredient.CODEC_NONEMPTY, 1, 3).fieldOf(\"ingredients\")"));
        assertTrue(r.contains("Codec.intRange(1, Integer.MAX_VALUE).optionalFieldOf(\"time\")"));
        assertTrue(r.contains("public int baseTime() { return time.orElseGet(() -> STANDARD_TIME * kind().timeFactor); }"));
        assertFalse(r.contains("\"slots\""));
        assertTrue(r.contains("AlloyResult.CODEC.fieldOf(\"result\")"));
    }

    @Test void jeiHasTwoCategoriesAndModeClickArea() throws Exception {
        var j = src("compat/jei/JeiCompat.java");
        assertTrue(j.contains("new EfficientSmeltingCategory("));
        assertTrue(j.contains("addRecipeCatalyst(ModBlocks.ALLOY_FURNACE_ITEM.get(), ALLOYING, EFFICIENT)"));
        assertTrue(j.contains("screen.efficientMode() ? EFFICIENT : ALLOYING"));
        assertFalse(j.contains("addRecipeClickArea(AlloyFurnaceScreen.class"));
        assertTrue(j.contains("ModRecipes.availableEfficient(level)"));
        var c = src("compat/jei/EfficientSmeltingCategory.java");
        assertTrue(c.contains("IDrawableAnimated.StartDirection.BOTTOM, false"));
        assertTrue(c.contains("implements IRecipeCategory<EfficientGroup>"));
        assertTrue(c.contains("int ticks = group.shape().ticks();"));
        assertTrue(c.contains("EfficientGrouping.focus(rows,"));
        assertTrue(j.contains("RecipeType.create(AAMoreAdditions.MODID, \"efficient_smelting\", EfficientGroup.class)"));
        assertTrue(j.contains("EfficientGroup.build(ModRecipes.availableEfficient(level))"));
        assertTrue(j.contains("addRecipeTransferHandler(new EfficientTransferHandler(reg.getTransferHelper()), EFFICIENT)"));
        var t = src("compat/jei/EfficientTransferHandler.java");
        assertTrue(t.contains("AlloyTransfer.simulate(player, menu.furnace, id, h.value())"));
        var at = src("menu/AlloyTransfer.java");
        assertTrue(at.contains("counts[i] = recipe.ingredientAmount(i);"));
        assertTrue(at.contains("ModRecipes.furnaceById(player.level(), recipeId)"));
        for (String lang : List.of("en_us", "zh_cn")) {
            var l = JsonParser.parseString(Files.readString(Path.of("src/main/resources/assets/aamoreadditions/lang/" + lang + ".json"))).getAsJsonObject();
            assertEquals(lang.equals("en_us") ? "Alloy Furnace: Alloy" : "合金炉：合金", l.get("jei.aamoreadditions.alloying").getAsString());
            assertEquals(lang.equals("en_us") ? "Alloy Furnace: Efficient Smelting" : "合金炉：高效烧炼", l.get("jei.aamoreadditions.efficient_smelting").getAsString());
        }
    }

    @Test void guiFlameReplacesArrowInEfficientMode() throws Exception {
        var s = src("client/screen/AlloyFurnaceScreen.java");
        assertTrue(s.contains("if (tile.efficientMode) renderFlameProgress(g);"));
        assertTrue(s.contains("FLAME_X = 106, FLAME_Y = 45, FLAME_SIZE = 14"));
        assertTrue(s.contains("ResourceLocation.withDefaultNamespace(\"container/furnace/lit_progress\")"));
        assertTrue(s.contains("RECIPE_AREA_X = 106, RECIPE_AREA_Y = 40, RECIPE_AREA_W = 14, RECIPE_AREA_H = 24")); // unchanged
        // flame lies inside the click area
        assertTrue(106 >= 106 && 106 + 14 <= 106 + 14 && 45 >= 40 && 45 + 14 <= 40 + 24);
    }

    @Test void alloyingDataTestDoesNotSeeEfficientRecipes() {
        assertFalse(DIR.startsWith(Path.of("src/main/resources/data/aamoreadditions/recipe/alloying")));
    }

    @Test void furnaceRunsEfficientRecipesWithLockAndTime() throws Exception {
        var be = src("block/AlloyFurnaceBlockEntity.java");
        assertTrue(be.contains("var match = com.aamoreadditions.recipe.ModRecipes.find(level, alloyInput(), efficientMode);"));
        assertTrue(be.contains("UpgradeEffects.time(this, match.recipe().value().baseTime())"));
        assertTrue(be.contains("if (com.aamoreadditions.recipe.EfficientMatcher.restartOnChange(efficientMode, lastRecipeId, id)) firstSmeltTime = 0;"));
        // the recipe the progress belongs to survives save/reload
        assertTrue(be.contains("compound.putString(\"AAMAEffRecipe\", lastRecipeId);"));
        assertTrue(be.contains("lastRecipeId = compound.contains(\"AAMAEffRecipe\")"));
        // JEI: plain ItemStack slots (JEI's normal item renderer -> blocks isometric), no custom item drawing
        var cat = src("compat/jei/EfficientSmeltingCategory.java");
        assertFalse(cat.contains("renderItem") || cat.contains("renderFakeItem") || cat.contains("textures/block"));
        assertTrue(be.contains("public int getFirstTimeToScale(int i)"));
        int t = be.indexOf("public void toggleMode()");
        String toggle = be.substring(t, be.indexOf("}", t));
        assertTrue(toggle.contains("firstSmeltTime = 0;") && toggle.contains("lock.unlock();"));
        assertTrue(be.contains("ModRecipes.furnaceById(level, lock.recipeId())"));
        var mr = src("recipe/ModRecipes.java");
        // both modes accept all inputs
        int i = mr.indexOf("public static boolean isIngredient(");
        String body = mr.substring(i, mr.indexOf("\n    }", i));
        assertTrue(body.contains("ALLOYING.get()") && body.contains("EFFICIENT.get()"));
    }
}
